function Decrypt-Files
{ 
param (
        [string]$Key,
        [string]$Folder
    )


    $files = Get-ChildItem -Path $Folder -Recurse -File | where {$_.extension -in ".enc"}

    foreach ( $f in $files) {
        Write-Host "DECRIPTING : " $f.FullName
        [Byte[]]$toDecript = [System.IO.File]::ReadAllBytes($f.FullName)
        [Byte[]]$decripted = Decrypt-Bytes -Key $kkey -InputBytes $toDecript
        [string]$newFilePath = $f.FullName.Substring(0, $f.FullName.Length - 4)
        [System.IO.File]::WriteAllBytes($newFilePath, $decripted)

        Remove-Item $f.FullName
    }
}


function Decrypt-Bytes  ([ValidateLength(32,32)] [string]$Key, [Byte[]]$InputBytes) 
{
$ByteKey              = [Byte[]][Char[]]$Key
$bytes                = $InputBytes
$aesManaged           = [System.Security.Cryptography.AesManaged]::new()
$aesManaged.Mode      = [System.Security.Cryptography.CipherMode]::CBC
$aesManaged.Padding   = [System.Security.Cryptography.PaddingMode]::PKCS7
$aesManaged.BlockSize = 128
$aesManaged.KeySize   = 256
$aesManaged.Key       = $ByteKey
$aesManaged.IV        = [System.Text.Encoding]::ASCII.GetBytes("!FAfrgaregQsg4w5")
$decryptor            = $aesManaged.CreateDecryptor()
$unencryptedData      = $decryptor.TransformFinalBlock($bytes, 0, $bytes.Length)
$aesManaged.Dispose()

return $unencryptedData
}


